output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Carts are prohibited in single-file shelf aisles where shelves flank both sides.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "park_cart_before_entering_single_file_aisle",
    "text": "A shopper must not enter a single-file shelf aisle while still holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileShelfAisle": {
          "pre": "MOVE",
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "enterSingleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "After parking or releasing a cart, the shopper is obliged to retrieve a cart again before finishing.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "pickUpCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "dropCart",
      "discharge": "pickUpCart"
    }
  },
  {
    "id": "only_park_cart_in_wide_cross_aisle",
    "text": "A cart may be parked only in a wide unobstructed aisle space, not beside shelves or in a constricted aisle.",
    "abstraction": {
      "state_properties": {
        "wideUnobstructedAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "wideUnobstructedAisle"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_for_wide_shelf_interaction",
    "text": "Shelf interactions from wide cart-accessible aisles must be performed while holding the cart.",
    "abstraction": {
      "state_properties": {
        "wideShelfAccess": {
          "and": [
            "adjShelf",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wideShelfAccess",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cartless_wandering_outside_handcarry_zone",
    "text": "Once away from the entrance/cart bay, being without a cart is allowed only at a cart-parking mouth or inside a hand-carry shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartBayOrEntrance": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartParkingMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "allowedNoCartZone": {
          "or": [
            "cartBayOrEntrance",
            "cartParkingMouth",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "not": "allowedNoCartZone"
          }
        ]
      }
    }
  },
  {
    "id": "return_to_mouth_after_entering_handcarry_aisle",
    "text": "A shopper who enters a single-file shelf aisle without a cart is obliged to return to a cart-parking mouth.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "cartParkingMouthNoCart": {
          "and": [
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            },
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "singleFileShelfAisle",
          {
            "not": "hasCart"
          }
        ]
      },
      "discharge": "cartParkingMouthNoCart"
    }
  },
  {
    "id": "single_file_aisles_are_vertical_only",
    "text": "In single-file shelf aisles, shoppers must not move horizontally between the flanking shelves.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          {
            "or": [
              "E",
              "W"
            ]
          }
        ]
      }
    }
  }
]
